// SPDX-License-Identifier: GPL-3.0-or-later
//! Rust literal emission shared by the generators: names, string/float literals, `PropDef`
//! and `FuncDef` expressions, and a per-crate pool of deduplicated enum item tables.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use super::model::{Def, EnumDef, Func, Item, Kind, Prop, Res, Shape};

/// Header of every generated Rust file.
pub fn header(what: &str) -> String {
    format!(
        "// SPDX-License-Identifier: GPL-3.0-or-later\n// @generated by `cargo xtask codegen` from spec/ (Blender 5.2.4 dumps + spec/overlay). DO NOT EDIT.\n//! {what}\n"
    )
}

pub const RUST_KEYWORDS: &[&str] = &[
    "as", "break", "const", "continue", "crate", "else", "enum", "extern", "false", "fn", "for",
    "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return",
    "self", "Self", "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where",
    "while", "async", "await", "dyn", "abstract", "become", "box", "do", "final", "macro",
    "override", "priv", "typeof", "unsized", "virtual", "yield", "try", "gen",
];

/// "MeshVertex" -> "MESH_VERTEX", "ID" -> "ID", "UVLoopLayers" -> "UV_LOOP_LAYERS".
pub fn screaming(ident: &str) -> String {
    let chars: Vec<char> = ident.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if c == '_' {
            if !out.ends_with('_') {
                out.push('_');
            }
            continue;
        }
        if c.is_ascii_uppercase() && i > 0 {
            let prev = chars[i - 1];
            let next_lower = chars.get(i + 1).is_some_and(|n| n.is_ascii_lowercase());
            if (prev.is_ascii_lowercase()
                || prev.is_ascii_digit()
                || (prev.is_ascii_uppercase() && next_lower))
                && !out.ends_with('_')
            {
                out.push('_');
            }
        }
        out.push(c.to_ascii_uppercase());
    }
    out
}

/// snake_case of a struct identifier.
pub fn snake(ident: &str) -> String {
    screaming(ident).to_ascii_lowercase()
}

/// "primitive_cube_add" -> "PrimitiveCubeAdd"; "XYZ_LENGTH" -> "XyzLength".
pub fn camel(ident: &str) -> String {
    let mut out = String::new();
    for part in ident.split(|c: char| !c.is_ascii_alphanumeric()) {
        let mut cs = part.chars();
        if let Some(f) = cs.next() {
            out.push(f.to_ascii_uppercase());
            out.extend(cs.map(|c| c.to_ascii_lowercase()));
        }
    }
    out
}

/// A field / module identifier, raw when it is a keyword.
pub fn ident(id: &str) -> String {
    if RUST_KEYWORDS.contains(&id) {
        format!("r#{id}")
    } else {
        id.to_owned()
    }
}

pub fn lit_str(s: &str) -> String {
    format!("{s:?}")
}

pub fn lit_f64(v: f64) -> String {
    if v.is_nan() {
        "f64::NAN".into()
    } else if v == f64::INFINITY {
        "f64::INFINITY".into()
    } else if v == f64::NEG_INFINITY {
        "f64::NEG_INFINITY".into()
    } else {
        let s = format!("{v:?}");
        if s.contains('.') || s.contains('e') {
            s
        } else {
            format!("{s}.0")
        }
    }
}

pub fn lit_f32(v: f64) -> String {
    let f = v as f32;
    if f.is_nan() {
        "f32::NAN".into()
    } else if f == f32::INFINITY {
        "f32::INFINITY".into()
    } else if f == f32::NEG_INFINITY {
        "f32::NEG_INFINITY".into()
    } else {
        let s = format!("{f:?}");
        if s.contains('.') || s.contains('e') {
            s
        } else {
            format!("{s}.0")
        }
    }
}

/// Subtype variant of `frap_rna::Subtype` for a Blender identifier.
pub fn subtype_variant(s: &str) -> Res<String> {
    const ALL: &[&str] = &[
        "NONE",
        "FILE_PATH",
        "DIR_PATH",
        "FILE_NAME",
        "BYTE_STRING",
        "PASSWORD",
        "PIXEL",
        "PIXEL_DIAMETER",
        "UNSIGNED",
        "PERCENTAGE",
        "FACTOR",
        "MASS",
        "ANGLE",
        "TIME",
        "TIME_ABSOLUTE",
        "DISTANCE",
        "DISTANCE_DIAMETER",
        "DISTANCE_CAMERA",
        "POWER",
        "TEMPERATURE",
        "WAVELENGTH",
        "COLOR_TEMPERATURE",
        "FREQUENCY",
        "COLOR",
        "TRANSLATION",
        "DIRECTION",
        "VELOCITY",
        "ACCELERATION",
        "MATRIX",
        "EULER",
        "QUATERNION",
        "AXISANGLE",
        "XYZ",
        "XYZ_LENGTH",
        "COLOR_GAMMA",
        "COORDINATES",
        "LAYER",
        "LAYER_MEMBER",
    ];
    if !ALL.contains(&s) {
        return Err(format!(
            "unknown subtype {s} (frap_rna::Subtype is incomplete)"
        ));
    }
    Ok(if s == "AXISANGLE" {
        "AxisAngle".into()
    } else {
        camel(s)
    })
}

/// Unit variant of `frap_rna::Unit`.
pub fn unit_variant(s: &str) -> Res<String> {
    const ALL: &[&str] = &[
        "NONE",
        "LENGTH",
        "AREA",
        "VOLUME",
        "ROTATION",
        "TIME",
        "TIME_ABSOLUTE",
        "VELOCITY",
        "ACCELERATION",
        "MASS",
        "CAMERA",
        "POWER",
        "TEMPERATURE",
        "WAVELENGTH",
        "COLOR_TEMPERATURE",
        "FREQUENCY",
    ];
    if !ALL.contains(&s) {
        return Err(format!("unknown unit {s} (frap_rna::Unit is incomplete)"));
    }
    Ok(camel(s))
}

/// Deduplicated `[EnumItem; n]` tables of one crate (`<path>::E<n>`).
#[derive(Default)]
pub struct EnumPool {
    index: BTreeMap<String, usize>,
    tables: Vec<Vec<Item>>,
}

impl EnumPool {
    /// Returns the table name for these items.
    pub fn intern(&mut self, items: &[Item]) -> String {
        let key = items
            .iter()
            .map(|i| format!("{}\u{1}{}\u{1}{}\u{1}{}", i.id, i.name, i.desc, i.value))
            .collect::<Vec<_>>()
            .join("\u{2}");
        let n = match self.index.get(&key) {
            Some(n) => *n,
            None => {
                self.tables.push(items.to_vec());
                self.index.insert(key, self.tables.len() - 1);
                self.tables.len() - 1
            }
        };
        format!("E{n}")
    }
    /// The `enums.rs` module source.
    pub fn module(&self, what: &str) -> String {
        let mut s = header(what);
        s.push_str("use frap_rna::EnumItem;\n\n");
        s.push_str(&self.statics());
        s
    }
    /// The `pub static E<n>: [EnumItem; k]` items only.
    pub fn statics(&self) -> String {
        let mut s = String::new();
        for (n, items) in self.tables.iter().enumerate() {
            let _ = writeln!(s, "pub static E{n}: [EnumItem; {}] = [", items.len());
            for i in items {
                let _ = writeln!(
                    s,
                    "    EnumItem {{ identifier: {}, name: {}, description: {}, value: {} }},",
                    lit_str(&i.id),
                    lit_str(&i.name),
                    lit_str(&i.desc),
                    i.value
                );
            }
            s.push_str("];\n");
        }
        s
    }
}

fn defaults<T>(d: &Def<T>, lit: impl Fn(&T) -> String) -> String {
    match d {
        Def::Scalar(v) => format!("Defaults::Scalar({})", lit(v)),
        Def::Array(a) => format!(
            "Defaults::Array(&[{}])",
            a.iter().map(lit).collect::<Vec<_>>().join(", ")
        ),
    }
}

fn shape_lit(s: Shape) -> String {
    match s {
        Shape::Scalar => "ArrayShape::Scalar".into(),
        Shape::Fixed(n) => format!("ArrayShape::Fixed({n})"),
        Shape::Matrix(r, c) => format!("ArrayShape::Matrix({r}, {c})"),
        Shape::Dynamic => "ArrayShape::Dynamic".into(),
    }
}

pub fn flags_lit(ty: &str, flags: &[String]) -> String {
    if flags.is_empty() {
        return format!("{ty}::empty()");
    }
    let mut it = flags.iter();
    let first = format!("{ty}::{}", it.next().expect("invariant: non-empty"));
    it.fold(first, |acc, f| format!("{acc}.union({ty}::{f})"))
}

/// A `PropDef { … }` expression. `pool_path` prefixes enum tables (`crate::generated::enums`).
pub fn prop_lit(p: &Prop, pool: &mut EnumPool, pool_path: &str) -> Res<String> {
    let kind = match &p.kind {
        Kind::Bool(d) => format!(
            "PropKind::Bool {{ default: {} }}",
            defaults(d, |b| b.to_string())
        ),
        Kind::Int {
            default,
            hard,
            soft,
        } => format!(
            "PropKind::Int {{ default: {}, hard: ({}, {}), soft: ({}, {}) }}",
            defaults(default, |v| v.to_string()),
            hard.0,
            hard.1,
            soft.0,
            soft.1
        ),
        Kind::Float {
            default,
            hard,
            soft,
            precision,
            f64_storage,
        } => format!(
            "PropKind::Float {{ default: {}, hard: ({}, {}), soft: ({}, {}), precision: {precision}, storage: FloatStorage::{} }}",
            defaults(default, |v| lit_f64(*v)),
            lit_f64(hard.0),
            lit_f64(hard.1),
            lit_f64(soft.0),
            lit_f64(soft.1),
            if *f64_storage { "F64" } else { "F32" }
        ),
        Kind::Str { default, max_bytes } => format!(
            "PropKind::String {{ default: {}, max_bytes: {max_bytes} }}",
            lit_str(default)
        ),
        Kind::Enum {
            items,
            default,
            dynamic,
            ..
        } => {
            let items = if items.is_empty() {
                "&[]".to_owned()
            } else {
                format!("&{pool_path}::{}", pool.intern(items))
            };
            let default = match default {
                EnumDef::Item(d) => format!("EnumDefault::Item({})", lit_str(d)),
                EnumDef::Flags(f) => format!(
                    "EnumDefault::Flags(&[{}])",
                    f.iter().map(|x| lit_str(x)).collect::<Vec<_>>().join(", ")
                ),
            };
            let dynamic = match dynamic {
                Some(k) => format!("Some({})", lit_str(k)),
                None => "None".into(),
            };
            format!("PropKind::Enum {{ items: {items}, default: {default}, dynamic: {dynamic} }}")
        }
        Kind::Pointer { fixed_type, is_id } => format!(
            "PropKind::Pointer {{ fixed_type: {}, is_id: {is_id} }}",
            lit_str(fixed_type)
        ),
        Kind::Coll { item_type, api } => format!(
            "PropKind::Collection {{ item_type: {}, api: {} }}",
            lit_str(item_type),
            match api {
                Some(a) => format!("Some({})", lit_str(a)),
                None => "None".into(),
            }
        ),
    };
    let deprecated = match &p.deprecated {
        Some(d) => format!(
            "Some(&Deprecation {{ note: {}, version: {:?}, removal_version: {:?} }})",
            lit_str(&d.note),
            d.version,
            d.removal_version
        ),
        None => "None".into(),
    };
    Ok(format!(
        "PropDef {{ identifier: {}, name: {}, description: {}, kind: {kind}, subtype: Subtype::{}, unit: Unit::{}, array: {}, flags: {}, deprecated: {deprecated} }}",
        lit_str(&p.identifier),
        lit_str(&p.name),
        lit_str(&p.description),
        subtype_variant(&p.subtype)?,
        unit_variant(&p.unit)?,
        shape_lit(p.array),
        flags_lit("PropFlags", &p.flags),
    ))
}

/// A `FuncDef { … }` expression.
pub fn func_lit(f: &Func, pool: &mut EnumPool, pool_path: &str) -> Res<String> {
    let list = |ps: &[Prop], pool: &mut EnumPool| -> Res<String> {
        let v: Vec<String> = ps
            .iter()
            .map(|p| prop_lit(p, pool, pool_path))
            .collect::<Res<_>>()?;
        Ok(if v.is_empty() {
            "&[]".into()
        } else {
            format!("&[\n            {},\n        ]", v.join(",\n            "))
        })
    };
    Ok(format!(
        "FuncDef {{\n        identifier: {},\n        description: {},\n        params: {},\n        returns: {},\n        keyword_only_from: {},\n        flags: {},\n    }}",
        lit_str(&f.identifier),
        lit_str(&f.description),
        list(&f.params, pool)?,
        list(&f.returns, pool)?,
        match f.keyword_only_from {
            Some(k) => format!("Some({k})"),
            None => "None".into(),
        },
        flags_lit("FuncFlags", &f.flags),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names() {
        assert_eq!(screaming("MeshVertex"), "MESH_VERTEX");
        assert_eq!(screaming("ID"), "ID");
        assert_eq!(screaming("UVLoopLayers"), "UV_LOOP_LAYERS");
        assert_eq!(
            screaming("ShaderNodeBsdfPrincipled"),
            "SHADER_NODE_BSDF_PRINCIPLED"
        );
        assert_eq!(screaming("GLTF_AddonPreferences"), "GLTF_ADDON_PREFERENCES");
        assert_eq!(screaming("Float2Attribute"), "FLOAT2_ATTRIBUTE");
        assert_eq!(camel("XYZ_LENGTH"), "XyzLength");
        assert_eq!(camel("primitive_cube_add"), "PrimitiveCubeAdd");
        assert_eq!(subtype_variant("AXISANGLE").unwrap(), "AxisAngle");
        assert_eq!(lit_f64(2.0), "2.0");
        assert_eq!(lit_f64(1e-5), "1e-5");
        assert_eq!(lit_f32(0.800000011920929), "0.8");
        assert_eq!(ident("type"), "r#type");
    }
}
